mat2 R2D(float r){return mat2(cos(r),-sin(r),sin(r),cos(r));}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

  vec2 uv = (gl_FragCoord.xy/iResolution.xy-.5)/vec2(iResolution.y/iResolution.x,1.);
  vec2 R2D = uv*R2D(iTime/8.);
  float BPM = 135.;
  float Luv = length(uv);
  vec3 col = .5+.5*cos(iTime+uv.xyx+vec3(0,2,4));
  float frac = fract(iTime*BPM/60.);
  float T8 = iTime*8.;
  vec3 Fog = vec3(.1)/Luv*4.;
  vec4 COL = vec4(0.);

  float pattern = ceil(length(sin(R2D-R2D*50./frac))-.2/Luv*frac);
  float pattern2 = ceil(length(sin(T8-(R2D*frac*R2D*50.)))-.2/Luv*frac);
  float pattern3 = ceil(sin(iTime*20.+R2D.x-frac/Luv/Luv*5./sin(iTime/8.)*2.));
  float pattern4 = ceil(length(sin(T8-(R2D.y*50.)))-.2/Luv/Luv+frac);
  float pattern5 = ceil(sin(T8-Luv*Luv/R2D.x*50.-frac));
  float pattern6 = ceil(sin(T8-uv.x*50./R2D.x*Luv-frac));

  float final = 0.;
  float modu = mod(iTime,24.);

  if(modu <= 4.){
  final = pattern;
  }else if(modu <= 8.){
  final = pattern2;
  }else if(modu <= 12.){
  final = pattern3;
  }else if(modu <= 16.){
  final = pattern4;
  }else if(modu <= 20.){
  final = pattern5;
  }else if(modu <= 24.){
  final = pattern6;
  }

  vec4 final2 = vec4(final*Fog*col,1.);
  vec4 final3 = sqrt(COL);
  vec4 final4 = max(final2,final3);

    fragColor = vec4(final4*final2);
}
